text:
Acá va un componente cliente para Next.js (App Router) con GSAP ScrollTrigger, actualizando el ancho de la barra desde `onUpdate`:

```tsx
// components/ScrollProgressBar.tsx
"use client";

import { useEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export default function ScrollProgressBar() {
  const barRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const bar = barRef.current;
    if (!bar) return;

    const ctx = gsap.context(() => {
      ScrollTrigger.create({
        start: 0,
        end: "max",
        onUpdate: (self) => {
          gsap.set(bar, { scaleX: self.progress });
        },
      });
    });

    return () => ctx.revert();
  }, []);

  return (
    <div
      className="fixed top-0 left-0 z-50 h-1 w-full bg-transparent"
      aria-hidden="true"
    >
      <div
        ref={barRef}
        className="h-full w-full origin-left bg-black scale-x-0"
      />
    </div>
  );
}
```

Uso (en el layout raíz, para que quede fija en toda la página):

```tsx
// app/layout.tsx
import ScrollProgressBar from "@/components/ScrollProgressBar";

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="es">
      <body>
        <ScrollProgressBar />
        {children}
      </body>
    </html>
  );
}
```

Notas:
- Uso `scaleX` en vez de `width` para que la animación corra en compositor (GPU) y no dispare layout en cada `onUpdate`.
- `end: "max"` referencia el scroll total del documento, así el progreso va de 0 a 1 en toda la página. Si el scroll ocurre dentro de un contenedor específico en vez del `body`, avisame y ajusto el `scroller` del `ScrollTrigger`.
- Color de la barra (`bg-black`) es placeholder — decime la paleta y lo ajusto con `@theme` de Tailwind v4.
- `gsap.context` limpia el `ScrollTrigger` al desmontar, para evitar duplicados en navegación client-side.

